svg.script:
const contentDiv = document.getElementById('launch-content');

window.addEventListener('message', function(event) {
  if (event.data && typeof event.data === 'string' && event.data.startsWith('CONTENT:')) {
    const htmlContent = event.data.slice(8);
    try {
      contentDiv.innerHTML = htmlContent;
      if (window.parent && window.parent !== window) {
        window.parent.postMessage({ type: 'content-loaded', source: 'launch-svg' }, '*');
      }
    } catch (e) {
      if (window.parent && window.parent !== window) {
        window.parent.postMessage({ type: 'content-error', source: 'launch-svg', error: e.message }, '*');
      }
    }
  }
});

if (window.parent && window.parent !== window) {
  window.parent.postMessage({ type: 'ready', source: 'launch-svg' }, '*');
}
